uniform float speed : 0.0 .. 5.0 = 1.0;
uniform float density : 0.0 .. 1.0 = 0.5;
uniform float brightness : 0.0 .. 2.0 = 1.0;
uniform vec3 color : color = 1.0, 1.0, 1.0;
uniform float twinkle : 0.0 .. 5.0 = 2.0;

state fixed star_ph;
state float twinkle_phase;

void update() {
  star_ph = fract(star_ph + fixed(dt * speed * 0.01));
  twinkle_phase = fract(twinkle_phase + dt * twinkle * 0.5);
}

vec3 shade(Led led) {
  // star field: use density and led.idx to scatter stars
  fixed star = fixed(led.idx) * fixed(density) * fixed(0.01);
  fixed x = led.pos.x;
  fixed y = led.pos.y;
  fixed z = led.pos.z;

  // distance from center of helix (project to XY)
  fixed dx = x;
  fixed dz = z;
  fixed dist2 = dx*dx + dz*dz;
  fixed dist = sqrt(dist2);

  // star brightness based on distance and phase
  fixed star_bright = sin(fixed(0.5) - dist * fixed(5.0) + star_ph) * fixed(0.5) + fixed(0.5);
  star_bright = clamp(star_bright, fixed(0.0), fixed(1.0));

  // twinkle: add a sinusoidal modulation based on twinkle_phase and position
  fixed twinkle_mod = sin(fixed(led.s) * fixed(twinkle) * fixed(0.1) + twinkle_phase) * fixed(0.2) + fixed(0.9);
  fixed final_bright = star_bright * twinkle_mod * fixed(brightness);

  // map to HSV then back to RGB
  fixed h = fract(fixed(led.s) * fixed(0.5) + star_ph);
  fixed s = fixed(0.9);
  fixed v = final_bright;
  vec3 rgb = hsv2rgb(h, s, v);

  return color * rgb;
}

